// Allow only web links; everything else becomes a harmless "#".
function safeHref(input) {
  let u;
  try { u = new URL(input, "https://shop.example"); } catch { return "#"; }
  return u.protocol === "https:" || u.protocol === "http:" ? u.href : "#";
}

