// One reviewed policy for the whole app.
const appPolicy = trustedTypes.createPolicy("app", {
  createHTML: input => DOMPurify.sanitize(input),
  createScriptURL: input => {
    const u = new URL(input, location.origin);
    if (u.origin === location.origin && u.pathname.startsWith("/js/")) return u.href;
    throw new TypeError("script URL not allowed: " + input);
