// Fetch Metadata check, with an Origin fallback for old browsers.
function sameOriginOnly(req, res, next) {
  const site = req.get("Sec-Fetch-Site");
  if (site) return site === "same-origin" ? next() : res.status(403).end();
  if (req.get("Origin") === "https://app.example") return next();
  return res.status(403).end();       // no usable header: fail closed
}

// Constant-time comparison of the submitted token.
function tokenOk(sent, want) {
  const a = Buffer.from(String(sent ?? "")), b = Buffer.from(want);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

