import crypto from "node:crypto";

// Hash every script a page loads, compare with a reviewed baseline.
async function scriptHashes(pageUrl) {
  const html = await (await fetch(pageUrl)).text();
  const srcs = [...html.matchAll(/<script[^>]*\bsrc="([^"]+)"/g)]
    .map(m => new URL(m[1], pageUrl).href);
  const out = {};
  for (const src of srcs) {
    const body = Buffer.from(await (await fetch(src)).arrayBuffer());
    out[src] = crypto.createHash("sha256").update(body).digest("base64");
  }
  return out;
}

function diff(baseline, now) {
  const alerts = [];
  for (const [src, h] of Object.entries(now)) {
    if (!(src in baseline)) alerts.push("NEW script " + src);
    else if (baseline[src] !== h) alerts.push("CHANGED " + src);
  }
  return alerts;
}
