import express from "express";
const app = express();
app.use(express.json({ type: "application/reports+json" }));

const seen = new Map();   // in production: a counter in your log pipeline
app.post("/csp-reports", (req, res) => {
  const reports = Array.isArray(req.body) ? req.body : [req.body];
  for (const r of reports) {
    if (r.type !== "csp-violation") continue;
    const b = r.body;
    // Group by page, directive and what was blocked.
    const key = [new URL(b.documentURL).pathname, b.effectiveDirective,
                 b.blockedURL, b.sample ?? ""].join(" | ");
    const n = (seen.get(key) ?? 0) + 1;
    seen.set(key, n);
    if (n === 1 || n === 50) console.log(`csp ${n}x: ${key}`);
  }
  res.sendStatus(204);
});
